//! Bulk English regressions: contractions, caps-lock autocorrection and
//! single-letter suggestions.
//!
//! The all-caps cases live in `data/all_caps_cases.tsv` and are regenerated by
//! `cargo run --release --example make_all_caps_cases`. The contraction and
//! single-letter suites are generated from the live language/layout data so a
//! new contraction or layout is covered automatically.

use type1_core::language::ENGLISH_CONTRACTIONS;
use type1_core::layout::{Layout, AZERTY, QWERTY};
use type1_core::lexicon::fold;
use type1_core::{Action, Engine};

const TEXT: i32 = 0x0000_0001;
const CAP_CHARACTERS: i32 = 0x0000_1000;

fn parse_cases(source: &'static str) -> Vec<(&'static str, &'static str)> {
	source
	. lines()
	. filter_map(|line| {
		let (typed, expected) = line.split_once('\t')?;
		if typed.is_empty() || expected.is_empty() {
			return None;
		}
		Some((typed, expected))
	})
	. collect()
}

fn suggestions(engine: &mut Engine) -> Vec<String> {
	let json: serde_json::Value =
		serde_json::from_str(&engine.render_json()).unwrap();
	json["suggestions"]
	. as_array()
	. unwrap()
	. iter()
	. map(|value| value.as_str().unwrap().to_string())
	. collect()
}

#[derive(Clone, Copy, Debug)]
enum Case {
	Lower,
	Capitalized,
	Upper,
}

fn cased(text: &str, case: Case) -> String {
	match case {
		Case::Lower => text.to_string(),
		Case::Capitalized => {
			let mut chars = text.chars();
			match chars.next() {
				Some(first) => first.to_uppercase().collect::<String>() + chars.as_str(),
				None => String::new(),
			}
		}
		Case::Upper => text.to_uppercase(),
	}
}

fn type_with_case(engine: &mut Engine, text: &str, case: Case) {
	match case {
		Case::Lower => {}
		Case::Capitalized => {
			engine.on_key("shift");
		}
		Case::Upper => {
			engine.on_key("shift");
			engine.on_key("shift");
		}
	}
	for ch in text.chars() {
		engine.on_key(&ch.to_string());
	}
}

/// One-key and two-key neighbours, using the same one-line geometry as the
/// corrector's cost table.
fn expected_neighbours(layout: &Layout, typed: char) -> Vec<char> {
	let Some((typed_index, typed_letter)) = layout
	. letters
	. iter()
	. enumerate()
	. find(|(_, letter)| letter.id.starts_with(typed))
	else {
		return Vec::new();
	};
	let mut neighbours: Vec<(char, f32)> = Vec::new();
	for (index, letter) in layout.letters.iter().enumerate() {
		let Some(other) = letter.id.chars().next() else {
			continue;
		};
		if other == typed {
			continue;
		}
		let dx = index as f32 - typed_index as f32;
		let dy = (letter.row as f32 - typed_letter.row as f32) * 0.55;
		let distance = (dx * dx + dy * dy).sqrt().min(2.6);
		if distance > 0.0 && distance <= 2.3 {
			neighbours.push((other, distance));
		}
	}
	neighbours.sort_by(|a, b| {
		a.1
		.partial_cmp(&b.1)
		.unwrap_or(std::cmp::Ordering::Equal)
		.then_with(|| a.0.cmp(&b.0))
	});
	neighbours.into_iter().map(|(letter, _)| letter).collect()
}

#[test]
fn thousands_of_all_caps_typos_are_corrected() {
	let cases = parse_cases(include_str!("data/all_caps_cases.tsv"));
	assert!(cases.len() >= 2_000, "only {} cases", cases.len());
	let mut engine = Engine::new();
	assert!(engine.set_profile_ids("qwerty", &["en"]));
	for (typed, expected) in cases {
		engine.set_input_type(TEXT | CAP_CHARACTERS, 0);
		for ch in typed.chars() {
			engine.on_key(&ch.to_ascii_lowercase().to_string());
		}
		assert_eq!(
			engine.on_key("space"),
			vec![
				Action::DeleteChars(typed.chars().count() as u32),
				Action::Commit(expected.into()),
				Action::Commit(" ".into()),
			],
			"typing {typed}"
		);
	}
}

fn fuzzy_contraction_cases() -> Vec<(&'static str, &'static str, &'static str)> {
	include_str!("data/fuzzy_contraction_cases.tsv")
	. lines()
	. filter_map(|line| {
		let mut parts = line.split('\t');
		Some((parts.next()?, parts.next()?, parts.next()?))
	})
	. collect()
}

#[test]
fn thousands_of_fuzzy_contractions_are_corrected() {
	let cases = fuzzy_contraction_cases();
	assert!(cases.len() >= 1_000, "only {} cases", cases.len());
	let mut checked = 0usize;
	for layout in ["azerty", "qwerty"] {
		let mut engine = Engine::new();
		assert!(engine.set_profile_ids(layout, &["en"]));
		for &(case_layout, typed, expected) in &cases {
			if case_layout != layout {
				continue;
			}
			for case in [Case::Lower, Case::Capitalized, Case::Upper] {
				engine.set_input_type(TEXT, 0);
				type_with_case(&mut engine, typed, case);
				assert_eq!(
					engine.on_key("space"),
					vec![
						Action::DeleteChars(typed.chars().count() as u32),
						Action::Commit(cased(expected, case)),
						Action::Commit(" ".into()),
					],
					"typing {typed} ({case:?}) on {layout}"
				);
				checked += 1;
			}
		}
	}
	assert!(
		checked >= 3_000,
		"only {checked} fuzzy contraction cases checked"
	);
}

#[test]
fn every_contraction_is_corrected_in_every_case_and_boundary() {
	let boundaries = [
		("space", " "),
		("comma", ","),
		("dot", "."),
		("sym::", ":"),
		("sym:;", ";"),
		("enter", "\n"),
	];
	let mut checked = 0usize;
	for layout in ["azerty", "qwerty"] {
		let mut engine = Engine::new();
		assert!(engine.set_profile_ids(layout, &["en"]));
		for &(typed, contraction) in ENGLISH_CONTRACTIONS {
			for case in [Case::Lower, Case::Capitalized, Case::Upper] {
				let expected = cased(contraction, case);
				for (key, boundary) in boundaries {
					engine.set_input_type(TEXT, 0);
					type_with_case(&mut engine, typed, case);
					assert_eq!(
						engine.on_key(key),
						vec![
							Action::DeleteChars(typed.chars().count() as u32),
							Action::Commit(expected.clone()),
							Action::Commit(boundary.to_string()),
						],
						"typing {typed} ({case:?}) then {key}"
					);
					checked += 1;
				}
			}
		}
	}
	assert!(
		checked >= 1_500,
		"only {checked} contraction cases checked"
	);
}

#[test]
fn every_single_letter_has_word_and_neighbour_suggestions() {
	let layouts: [(&str, &Layout); 2] = [("azerty", &AZERTY), ("qwerty", &QWERTY)];
	let languages: [&[&str]; 3] = [&["fr"], &["en"], &["fr", "en"]];
	let mut base_cases = 0usize;
	let mut neighbour_cases = 0usize;
	let mut failures: Vec<String> = Vec::new();

	for (layout_id, layout) in layouts {
		for language_set in languages {
			let mut engine = Engine::new();
			assert!(engine.set_profile_ids(layout_id, language_set));
			for letter in 'a'..='z' {
				let neighbours = expected_neighbours(layout, letter);
				for case in [Case::Lower, Case::Upper] {
					engine.set_input_type(TEXT, 0);
					type_with_case(&mut engine, &letter.to_string(), case);
					let list = suggestions(&mut engine);
					let typed = cased(&letter.to_string(), case);
					base_cases += 1;
					if list.is_empty() {
						failures.push(format!("{layout_id}/{language_set:?} {typed}: no suggestions"));
					}
					if list.len() > 6 {
						failures.push(format!(
							"{layout_id}/{language_set:?} {typed}: {} suggestions",
							list.len()
						));
					}
					if list.iter().any(|text| text == &typed) {
						failures.push(format!(
							"{layout_id}/{language_set:?} {typed}: suggests itself {list:?}"
						));
					}
					if matches!(case, Case::Upper)
						&& list.iter().any(|text| text.chars().any(|c| c.is_lowercase()))
					{
						failures.push(format!(
							"{layout_id}/{language_set:?} {typed}: lowercase in {list:?}"
						));
					}
					for &neighbour in &neighbours {
						neighbour_cases += 1;
						let present = list.iter().any(|text| {
							let folded = fold(&text.to_lowercase());
							folded.starts_with(neighbour)
						});
						if !present {
							failures.push(format!(
								"{layout_id}/{language_set:?} {typed}: missing {neighbour} in {list:?}"
							));
						}
					}
				}
			}
		}
	}

	assert!(base_cases >= 300, "only {base_cases} letter cases checked");
	assert!(
		neighbour_cases >= 1_000,
		"only {neighbour_cases} neighbour cases checked"
	);
	assert!(
		failures.is_empty(),
		"{} failures:\n{}",
		failures.len(),
		failures
		. iter()
		.take(25)
		.cloned()
		.collect::<Vec<_>>()
		. join("\n")
	);
}
